import functools
def merge(a):
    a = tuple(a)
    @functools.lru_cache(None)
    def f(t):
        if len(t) == 1: return 0
        return min(t[i] + t[i + 1] + f(t[:i] + (t[i] + t[i + 1],) + t[i + 2:]) for i in range(len(t) - 1))
    return f(a)
def chain(d):
    @functools.lru_cache(None)
    def f(t):
        if len(t) == 2: return 0
        return min(t[i - 1] * t[i] * t[i + 1] + f(t[:i] + t[i + 1:]) for i in range(1, len(t) - 1))
    return f(tuple(d))
result = merge([1, 2, 3])

