import itertools
def cost(order):
    pieces = [(0, 10)]; c = 0
    for m in order:
        a, b = next(p for p in pieces if p[0] < m < p[1]); c += b - a; pieces.remove((a, b)); pieces += [(a, m), (m, b)]
    return c
assert f(0, 4) == min(cost(o) for o in itertools.permutations((2, 4, 7)))
