import functools
@functools.lru_cache(None)
def f(t):
    if not t: return 0
    return 1 + min(f(t[:l] + t[r:]) for l in range(len(t)) for r in range(l + 1, len(t) + 1) if t[l:r] == t[l:r][::-1])
